use serde_json::{json,Value};
use ss_core::cn::wps::moss::{app::{KmoBookApi::KmoBookApi,KmoLocale::KmoLocale,KmoSheet::KmoSheet},engine::grid::{KmoCellData::KmoCellData,KmoCellValueStore::KmoCellValueStore}};
fn decode(v:&Value)->Option<String>{v.as_str().map(|s|String::from_utf16(&(0..s.len()).step_by(4).map(|i|u16::from_str_radix(&s[i..i+4],16).unwrap()).collect::<Vec<_>>()).unwrap())}
fn hex(s:&str)->String{s.encode_utf16().map(|c|format!("{c:04x}")).collect()}
#[test]
fn original_android_raw_only_numfmt_writeback(){
    let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/recognise-r0b27");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();KmoLocale::setLocale("zh_CN".into());kfc::cn::wps::kfc::numfmt::i18n::KmoLang::KmoLang::setLocale("zh_CN".into());let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let sheet=book.sheetAt(0);let s=sheet.borrow();KmoSheet::resetConstRecognLang();s.initConstRecognisor();let mut actual=vec![];
    for (i,row)in java["rawOnly"].as_array().unwrap().iter().enumerate(){let input=decode(&row["input"]);let seed=KmoCellData{ixf:15,hasComment:true,isPicInCell:true,id:book.getCellValueStore().borrow_mut().newDoubleValue(99.99),..Default::default()};s.setCellData(70,31,&seed);book.setDirty(false);let mut a=json!({"input":row["input"]});let r=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||s.setCellRawOnlyNumFmt(70,31,input.as_deref())));match r{Ok(v)=>a["numfmt"]=json!(v),Err(_)=>a["exception"]=json!("NumberFormatException")};let cell=s.getCellData(70,31);let bytes=cell.write(&mut [0;7]).iter().map(|b|format!("{b:02x}")).collect::<String>();let t=KmoCellValueStore::identifyTypeByID(cell.id);let xf=s.getCellXF__2(70,31).unwrap();a["bytes"]=json!(bytes);a["type"]=json!(t);a["dirty"]=json!(book.isDirty());a["formatIndex"]=json!(xf.getFormatIndex());a["format"]=json!(xf.getNumFormat());a["display"]=json!(s.getFormattedCellValue(70,31));if t==1{a["bits"]=json!(format!("{:016x}",s.getCellNumericValue(70,31).to_bits()));}if t==2{a["text"]=json!(hex(&s.getCellStringValue(70,31)));}assert_eq!(a,*row,"case {i}");actual.push(a);
    }
    std::fs::write(p.join("rust-raw-only.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
